import requests
headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
urls = {
    'dronethermal-v4': 'https://groupgets.com/manufacturers/flytron/products/dronethermal-v4',
    'horus': 'https://horusdynamics.com/shop/lepton-kit-hdk1500/',
}
for name, url in urls.items():
    try:
        r = requests.get(url, headers=headers, timeout=10)
        print(f'=== {name} (status={r.status_code}) ===')
        # look for price patterns
        import re
        prices = re.findall(r'\\\$[0-9]+\.?[0-9]{0,2}', r.text[:50000])
        for p in prices[:5]:
            print(f'  Price: {p}')
        # check title
        t = re.findall(r'<title>(.*?)</title>', r.text, re.DOTALL)
        if t: print(f'  Title: {t[0][:120]}')
    except Exception as e:
        print(f'{name}: ERROR {e}')
" 2>/dev/null

