import requests, re, json

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
# Amazon product page - search for price data inside JSON-LD or hidden data
url = 'https://www.amazon.com/dp/B0FS43Y4YP'
r = requests.get(url, headers=headers, timeout=15)

# Search for price data patterns
price_patterns = [
    r'\"price\"\s*:\s*\"?([0-9]+\.[0-9]{2})\"?',
    r'\$([0-9]+\.[0-9]{2})',
    r'\"priceAmount\"\s*:\s*\"?([0-9]+\.[0-9]{2})\"?',
    r'price_display.*?(\$[0-9]+\.[0-9]{2})',
    r'\$([0-9]+\.[0-9]{2})\s*\$',
]

# Look at JSON-LD schema
jsonld = re.findall(r'<script[^>]*type=\"application/ld\+json\"[^>]*>(.*?)</script>', r.text, re.DOTALL)
print('=== Generic 256x192 Amazon B0FS43Y4YP ===')
for j in jsonld[:3]:
    try:
        data = json.loads(j)
        if isinstance(data, dict):
            if 'offers' in data:
                offers = data['offers']
                if isinstance(offers, list):
                    for o in offers:
                        if 'price' in o:
                            print(f'  LD+JSON price: {o[\"price\"]}')
                elif isinstance(offers, dict) and 'price' in offers:
                    print(f'  LD+JSON price: {offers[\"price\"]}')
    except:
        pass
# Find with regex
for pat in price_patterns:
    m = re.findall(pat, r.text)
    if m:
        print(f'  Pattern match: {m[:5]}')
print()

